def sum_of_squares(iterable):
    """Return the sum of the squares of items in *iterable*.

    >>> sum_of_squares(range(5))  # 0^2 + 1^2 + 2^2 + 3^2 + 4^2
    30

    The input iterable may be any iterable of numbers.
    """
    return sum(x * x for x in iterable)

